<?php&#10;session_start();&#10;include("connect.php");&#10;&#10;// Function to get correct image path&#10;function cartImagePath($imageRaw) {&#10;    $raw = trim($imageRaw);&#10;    if ($raw === &#x27;&#x27;) {&#10;        return &#x27;skaff1.jpg&#x27;;&#10;    }&#10;    $candidates = array(&#10;        &#x27;admin/uploads/products/&#x27; . ltrim($raw, &#x27;/\\\\&#x27;),&#10;        &#x27;admin/uploads/&#x27; . ltrim($raw, &#x27;/\\\\&#x27;),&#10;        &#x27;uploads/products/&#x27; . ltrim($raw, &#x27;/\\\\&#x27;),&#10;        &#x27;uploads/&#x27; . ltrim($raw, &#x27;/\\\\&#x27;),&#10;        $raw&#10;    );&#10;    foreach ($candidates as $path) {&#10;        if (file_exists($path)) {&#10;            return $path;&#10;        }&#10;    }&#10;    return &#x27;skaff1.jpg&#x27;;&#10;}&#10;&#10;// Handle Update Cart Quantity&#10;if (isset($_POST[&#x27;update_cart&#x27;]) &amp;&amp; isset($_POST[&#x27;quantities&#x27;]) &amp;&amp; is_array($_POST[&#x27;quantities&#x27;])) {&#10;    foreach ($_POST[&#x27;quantities&#x27;] as $cart_id => $qty) {&#10;        $cart_id = intval($cart_id);&#10;        $qty = intval($qty);&#10;        &#10;        if ($cart_id <= 0) {&#10;            continue;&#10;        }&#10;        &#10;        if ($qty <= 0) {&#10;            // Remove item from cart&#10;            $delete = $con->prepare("DELETE FROM cart WHERE id = ?");&#10;            $delete->bind_param("i", $cart_id);&#10;            $delete->execute();&#10;        } else {&#10;            // Update quantity&#10;            $update = $con->prepare("UPDATE cart SET quantity = ? WHERE id = ?");&#10;            $update->bind_param("ii", $qty, $cart_id);&#10;            $update->execute();&#10;        }&#10;    }&#10;    header("Location: cart.php");&#10;    exit;&#10;}&#10;&#10;// Handle Remove Item&#10;if (isset($_GET[&#x27;action&#x27;]) &amp;&amp; $_GET[&#x27;action&#x27;] === &#x27;remove&#x27; &amp;&amp; isset($_GET[&#x27;id&#x27;])) {&#10;    $id = intval($_GET[&#x27;id&#x27;]);&#10;    $delete = $con->prepare("DELETE FROM cart WHERE id = ?");&#10;    $delete->bind_param("i", $id);&#10;    $delete->execute();&#10;    header("Location: cart.php");&#10;    exit;&#10;}&#10;&#10;// Fetch cart items from database&#10;$cart_items = array();&#10;$grandTotal = 0;&#10;&#10;$user_id = isset($_SESSION[&#x27;user_id&#x27;]) ? intval($_SESSION[&#x27;user_id&#x27;]) : 0;&#10;$sql = "SELECT cart.id, cart.product_id, cart.quantity, p.name, p.price, p.image FROM cart JOIN products p ON cart.product_id = p.id WHERE cart.user_id = ? ORDER BY cart.id DESC";&#10;$stmt = $con->prepare($sql);&#10;$stmt->bind_param("i", $user_id);&#10;$stmt->execute();&#10;$result = $stmt->get_result();&#10;if ($result &amp;&amp; $result->num_rows > 0) {&#10;    while ($row = $result->fetch_assoc()) {&#10;        $lineTotal = floatval($row[&#x27;price&#x27;]) * intval($row[&#x27;quantity&#x27;]);&#10;        $grandTotal += $lineTotal;&#10;        $cart_items[] = array(&#10;            &#x27;id&#x27; => intval($row[&#x27;id&#x27;]),&#10;            &#x27;product_id&#x27; => intval($row[&#x27;product_id&#x27;]),&#10;            &#x27;name&#x27; => $row[&#x27;name&#x27;],&#10;            &#x27;price&#x27; => floatval($row[&#x27;price&#x27;]),&#10;            &#x27;image&#x27; => $row[&#x27;image&#x27;],&#10;            &#x27;quantity&#x27; => intval($row[&#x27;quantity&#x27;]),&#10;            &#x27;line_total&#x27; => $lineTotal&#10;        );&#10;    }&#10;}&#10;?>&#10;<!DOCTYPE html>&#10;<html lang="en">&#10;<head>&#10;<meta charset="UTF-8">&#10;<meta name="viewport" content="width=device-width, initial-scale=1.0">&#10;<title>Cart - Haya Collection</title>&#10;<link rel="icon" type="image/x-icon" href="/php%20e-com/favicon.ico">&#10;<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">&#10;<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">&#10;<style>&#10;body{background:#f8f3f4;font-family:Arial,sans-serif}&#10;.wrap{max-width:1100px;margin:30px auto}&#10;.cardx{background:#fff;border-radius:16px;box-shadow:0 10px 24px rgba(122,62,62,.1);padding:20px}&#10;.title{color:#7a3e3e;font-weight:700}&#10;.item-img{width:80px;height:80px;border-radius:10px;object-fit:cover}&#10;.btn-main{background:#7a3e3e;border-color:#7a3e3e;color:#fff}&#10;.btn-main:hover{background:#623232;border-color:#623232;color:#fff}&#10;.btn-outline-danger{border-color:#dc3545;color:#dc3545}&#10;.btn-outline-danger:hover{background:#dc3545;color:#fff}&#10;&#10;/* Cart Table Styling */&#10;.cart-table { width: 100%; border-collapse: collapse; }&#10;.cart-table th { &#10;    background: #f8ecef; &#10;    color: #7a3e3e; &#10;    padding: 15px; &#10;    text-align: left; &#10;    font-weight: 600;&#10;}&#10;.cart-table td { &#10;    padding: 15px; &#10;    vertical-align: middle; &#10;    border-bottom: 1px solid #eee;&#10;}&#10;.cart-table tr:hover { background: #fafafa; }&#10;&#10;/* Product Info in Cart */&#10;.cart-product-info {&#10;    display: flex;&#10;    align-items: center;&#10;    gap: 15px;&#10;}&#10;.cart-product-info img {&#10;    width: 60px;&#10;    height: 60px;&#10;    object-fit: cover;&#10;    border-radius: 8px;&#10;}&#10;.cart-product-name {&#10;    font-weight: 600;&#10;    color: #333;&#10;    font-size: 16px;&#10;}&#10;&#10;/* Quantity Input */&#10;.qty-input {&#10;    width: 70px;&#10;    padding: 8px;&#10;    border: 1px solid #ddd;&#10;    border-radius: 5px;&#10;    text-align: center;&#10;}&#10;&#10;/* Remove Button */&#10;.remove-link {&#10;    color: #dc3545;&#10;    text-decoration: none;&#10;    font-size: 20px;&#10;    transition: transform 0.3s ease;&#10;}&#10;.remove-link:hover {&#10;    transform: scale(1.2);&#10;}&#10;&#10;.cart-checkbox {&#10;    width: 20px;&#10;    height: 20px;&#10;    cursor: pointer;&#10;}&#10;&#10;.selected-summary {&#10;    background: #e8f5e8;&#10;    border: 2px solid #28a745;&#10;    border-radius: 10px;&#10;    padding: 15px;&#10;}&#10;&#10;#proceedBtn:disabled {&#10;    background: #ccc;&#10;    border-color: #ccc;&#10;    cursor: not-allowed;&#10;}&#10;&#10;&#10;/* Empty Cart */&#10;.empty-cart {&#10;    text-align: center;&#10;    padding: 60px 20px;&#10;}&#10;.empty-cart-icon {&#10;    font-size: 60px;&#10;    margin-bottom: 20px;&#10;}&#10;.empty-cart h3 {&#10;    color: #7a3e3e;&#10;    margin-bottom: 15px;&#10;}&#10;&#10;/* Cart Summary */&#10;.cart-summary {&#10;    background: #f8ecef;&#10;    padding: 20px;&#10;    border-radius: 10px;&#10;    margin-top: 20px;&#10;}&#10;.summary-row {&#10;    display: flex;&#10;    justify-content: space-between;&#10;    padding: 10px 0;&#10;    border-bottom: 1px solid #e0d0d2;&#10;}&#10;.summary-row:last-child {&#10;    border-bottom: none;&#10;    font-size: 18px;&#10;    font-weight: 700;&#10;    color: #7a3e3e;&#10;}&#10;</style>&#10;<link rel="stylesheet" href="/php%20e-com/style.css">&#10;</head>&#10;<body>&#10;<div class="wrap container">&#10;    <div class="d-flex justify-content-between align-items-center mb-4">&#10;        <h3 class="title mb-0">Shopping Cart</h3>&#10;        <a href="shoppage2.php" class="btn btn-outline-secondary btn-sm">Continue Shopping</a>&#10;    </div>&#10;&#10;    <div class="cardx">&#10;        <?php if (empty($cart_items)): ?>&#10;            <div class="empty-cart">&#10;                <div class="empty-cart-icon">🛒</div>&#10;            <h3>Your cart is empty!</h3>&#10;            <p style="color: #666; margin-bottom: 20px;">Looks like you haven&#x27;t added anything to your spot. </p>&#10;            <a href="shoppage2.php" class="btn btn-main">Shop Now</a>&#10;            </div>&#10;        <?php else: ?>&#10;            <form method="post" action="cart.php">&#10;                <div class="table-responsive">&#10;                    <table class="cart-table">&#10;                        <thead>&#10;                            <tr>&#10;                                &text-align: left; &#10;    font-weight: 600;&#10;}&#10;.cart-table td { &#10;    padding: 15px; &#10;    vertical-align: middle; &#10;    border-bottom: 1px solid #eee;&#10;}&#10;.cart-table tr:hover { background: #fafafa; }&#10;&#10;/* Product Info in Cart */&#10;.cart-product-info {&#10;    display:  flex;&#10;    align-items: center;&#10;    gap: 15px;&#10;}&#10;.cart-product-info img {&#10;                                <th>Select</th>&#10;                                <th>Product</th>&#10;                                <th>Price</th>&#10;                                <th>Price</th>&#10;                                <th>Quantity</th>&#10;                                <th>Total</th>&#10;                                <th>Remove</th>&#10;                            </tr>&#10;                        </thead>&#10;                        &img src="<?php echo htmlspecialchars(cartImagePath($item[&#x27;image&#x27;])); ?>" alt="<?php echo htmlspecialchars($item[&#x27;id&#x27;]); ?>">&#10;                                        <span class="cart-product-name"><?php echo htmlspecialchars($item[&#x27;name&#x27;]); ?></span>&#10;                                    </div>&#10;                                </td>&#10;&#10;                                <td>₹<?php echo number_format($item[&#x27;price&#x27;], 2); ?></td>&#10;                                <td>&#10;                                    <input type="data-price="<?php echo $item[&#x27;price&#x27;]; ?>" data-qty="<?php echo $item[&#x27;quantity&#x27;]; ?>" data-total="<?php echo $item[&#x27;line_total&#x27;]; ?>">&#10;                                    <input type="number" min=<input type="checkbox" class="cart-checkbox" name="selected_items[]" value=<?php echo $item[&#x27;product_id&#x27;]; ?> data-price=<?php echo $item[&#x27;price&#x27;]; ?> data-qty=<?php echo $value="<?php echo intval($item[&#x27;quantity&#x27;]); ?>">&#10;                                    </td>&#10;                                    <td>₹<?php echo number_format($item[&#x27;line_total&#x27;]; 2); ?></td>&#10;                                    <td>&#10;                                    <a href="cart.php?action=remove&amp;id=<?php echo $item[&#x27;id&#x27;]; ?>" class="remove-link" title="Remove Item">&#10;                                        <i class="fas fa-trash-alt"></i>&#10;                                    </a>&#10;                                &line_total&#x27;); ?>">&#10;                                </td>&#10;                            </tr>&#10;                        <?php endforeach; ?>&#10;                        </tbody>&#10;                    </table>&#10;                </div>&#10;&#10;                <div class="d-flex justify-content-between align-items-center mt-4">&#10;                    <button type="submit" name="update_cart" class="btn btn-outline-secondary">&#10;                        <i class="fas fa-sync-alt"></i> Update Cart&#10;                    </button>&#10;                    <div class="cart-summary">&#10;                        <div class="summary-row">&#10;                            <span>All Items Subtotal:</span>&#10;                            <span>₹<?php echo number_format($grandTotal, 2); ?></span>&#10;                        </div>&#10;                        <div class="summary-row">&#10;                            <span>Shipping:</span>&#10;                            <span>Free</span>&#10;                        </div>&#10;                    </div>&#10;                </div>&#10;            </form>&#10;&#10;            <!-- Selected Items Checkout Form -->&#10;            <form method="POST" value="<?php echo intval($item[&#x27;quantity&#x27;]); ?>">&#10;            <form method="POST" action="checkout.php" id="checkoutForm">&#10;                <div class="selected-summary mt-4" id="selectedSummary" style="display: none;">&#10;                    <div class="cart-summary">&#10;                        <div class=&"summary-row" style="font-weight: bold; font-size: 18px;">&#10;                            <span>Total:</span>&#10;                            <span id="selectedTotal">₹0.00</span>&#10;                        </div>&#10;                    </div>&#10;                &div class="d-flex justify-content-end gap-2 mt-4">&#10;                    <button type="button" class="btn btn-outline-primary" id="selectAllBtn">Select All</button>&#10;                    <button type="submit" name="proceed_selected" class="btn btn-main btn-lg" id="proceedBtn" disabled>&#10;                        Proceed to Checkout&#10;                    </button>&#10;                </div>&#10;            </form>&#10;&#10;        <?php endif; ?>&#10;    </div>&#10;</div>&#10;<script>&#10;document.addEventListener(&#x27;DOMContentLoaded&#x27;, function() {&#10;    const checkboxes = document.querySelectorAll(&#x27;.cart-checkbox&#x27;);&#10;    const selectedSummary = document.getElementById(&#x27;selectedSummary&#x27;);&#10;    const selectedCountEl = document.getElementBy="document.getElementById(&#x27;selectedCount&#x27;);&#10;    const selectedSubtotalEl = document.getElementById(&#x27;selectedSubtotal&#x27;);&#10;    const selectedTotalEl = document.addEventListener(&#x27;submit&#x27;, function(e) {&#10;        const checkedBoxes = document.querySelectorAll(&#x27;.cart-checkbox:checked&#x27;);&#10;        if (checkedBoxes.length === 0) {&#10;            e.preventDefault();&#10;            alert(&#x27;Please select at least one product to proceed to checkout.&#x27;);&#10;            return false;&#10;        }&#10;    });&#10;});&#10;</script>&#10;<?php include &#x27;includes/global_footer.php&#x27;; ?>&#10;</body>&#10;</html>
